import React, { useCallback, useDeferredValue, useEffect, useMemo, useRef, useState } from 'react';
import {
  AlertTriangle,
  Check,
  ChevronLeft,
  ChevronRight,
  ClipboardCheck,
  Database,
  Eye,
  FileBox,
  Flag,
  FolderCog,
  Layers3,
  Palette,
  Pencil,
  Plus,
  RefreshCw,
  Save,
  Search,
  ShieldAlert,
  Trash2,
  X,
} from 'lucide-react';
import type { AdminRequest } from './adminRequest';
import { adminLabel, adminPageCount } from './adminPresentation';
import { AdminButton, AdminEmptyState, AdminErrorState, AdminLoading, AdminToolbar } from './AdminPrimitives';
import { ContentDrawer, jsonDraftText, useContentWrite } from './AdminContentFlow';

type ContentMode = 'colors-assets' | 'community';
type CardStatus = 'active' | 'disabled' | 'archived';
type AssetStatus = 'active' | 'deleted';
type AssetVisibility = 'private' | 'public' | 'restricted';
type ContentType = 'work' | 'post' | 'comment';
type ReportStatus = 'open' | 'reviewing' | 'resolved' | 'rejected';
type ModerationAction = 'approve' | 'hide' | 'remove' | 'restore' | 'feature' | 'unfeature';

interface Paged<T> { items: T[]; total: number; limit: number; offset: number; warnings?: string[]; }
interface ColorCard {
  id: string;
  brandKey: string;
  displayName: string;
  colorCount: number;
  sourceUrl: string | null;
  status: CardStatus;
  notes: string;
  swatchCount: number;
  updatedBy: string | null;
  createdAt: number;
  updatedAt: number;
}
interface ColorSwatch {
  id: string;
  cardId: string;
  colorCode: string;
  displayName: string;
  hex: string;
  rgb: { r: number; g: number; b: number };
  sortOrder: number;
  createdAt: number;
  updatedAt: number;
}
interface StorageAsset {
  id: string;
  objectKey: string;
  resourceType: string;
  contentType: string | null;
  byteSize: number;
  ownerUid: string | null;
  visibility: AssetVisibility;
  status: AssetStatus;
  metadata: unknown;
  createdAt: number;
  updatedAt: number;
}
interface CommunityContent {
  id: string;
  entityType: ContentType;
  title: string;
  authorUid: string | null;
  status: string | null;
  createdAt: number | null;
  updatedAt: number | null;
  moderation: ModerationRecord | null;
}
interface ContentReport {
  id: string;
  reporterUid: string | null;
  entityType: ContentType;
  entityId: string;
  reasonCode: string;
  description: string;
  status: ReportStatus;
  handledBy: string | null;
  handledAt: number | null;
  createdAt: number;
  updatedAt: number;
}
interface ModerationRecord {
  id: string;
  entityType: ContentType;
  entityId: string;
  action: ModerationAction;
  reason: string;
  metadata: unknown;
  operatorUid: string | null;
  createdAt: number;
}

export interface AdminContentResourcesProps { mode: ContentMode; request: AdminRequest; }

const PAGE_SIZE = 20;
const CARD_STATUSES: CardStatus[] = ['active', 'disabled', 'archived'];
const REPORT_STATUSES: ReportStatus[] = ['open', 'reviewing', 'resolved', 'rejected'];
const MODERATION_ACTIONS: ModerationAction[] = ['approve', 'hide', 'remove', 'restore', 'feature', 'unfeature'];
const HEX_PATTERN = /^#[0-9A-F]{6}$/;
const CARD_KEY_PATTERN = /^[a-z][a-z0-9_.-]{0,79}$/;

function time(value: number | null | undefined): string {
  if (!value) return '-';
  const date = new Date(value);
  return Number.isNaN(date.valueOf()) ? '-' : date.toLocaleString('zh-CN', { hour12: false });
}

function byteSize(value: number): string {
  if (!Number.isFinite(value) || value < 0) return '-';
  if (value < 1024) return `${value} B`;
  if (value < 1024 * 1024) return `${(value / 1024).toFixed(1)} KB`;
  return `${(value / 1024 / 1024).toFixed(1)} MB`;
}

function query(values: Record<string, string | number | null | undefined>): string {
  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(values)) {
    if (value !== undefined && value !== null && value !== '') params.set(key, String(value));
  }
  const output = params.toString();
  return output ? `?${output}` : '';
}

function getError(error: unknown, fallback: string): string {
  return error instanceof Error ? error.message : fallback;
}

function Notice({ children, tone = 'amber' }: { children: React.ReactNode; tone?: 'amber' | 'rose' | 'sky' }) {
  return tone === 'rose' ? <AdminErrorState message={String(children)} /> : <div className="admin-final-notice" role="status"><AlertTriangle aria-hidden="true" />{children}</div>;
}

function Loading() { return <AdminLoading />; }

function Empty({ children, error }: { children: React.ReactNode; error?: string }) { return <AdminEmptyState title={error ? "尚无可确认的读取结果" : String(children)} description={error ? "请点击刷新重试；读取失败不代表没有数据。" : undefined} />; }

function Pager({ page, total, onChange, busy = false }: { page: number; total: number; onChange: (page: number) => void; busy?: boolean }) {
  return <div className="admin-pagination"><span>共{total}条 · {page}/{adminPageCount(total, PAGE_SIZE)}页</span><div><AdminButton iconOnly aria-label="上一页" disabled={busy || page<=1} onClick={()=>onChange(page-1)}><ChevronLeft aria-hidden="true" /></AdminButton><AdminButton iconOnly aria-label="下一页" disabled={busy || page>=adminPageCount(total, PAGE_SIZE)} onClick={()=>onChange(page+1)}><ChevronRight aria-hidden="true" /></AdminButton></div></div>;
}

function Modal({ title, detail, children, close, busy = false }: { title: string; detail: string; children: React.ReactNode; close: () => void; busy?: boolean }) {
  return <ContentDrawer title={title} description={detail} busy={busy} onClose={close}><div className="admin-final-fields">{children}</div></ContentDrawer>;
}

function PanelHeading({ eyebrow, title, description, refresh, loading, create, createLabel, readOnly }: { eyebrow: string; title: string; description: string; refresh: () => void; loading: boolean; create?: () => void; createLabel?: string; readOnly: boolean }) {
  return <AdminToolbar actions={<><AdminButton busy={loading} onClick={refresh}>刷新</AdminButton>{create&&<AdminButton variant="primary" disabled={readOnly} onClick={create}><Plus aria-hidden="true" />{createLabel}</AdminButton>}</>}><h2>{title}</h2><p>{description}</p></AdminToolbar>;
}

function ColorCardEditor({ initial, onClose, onSave, saving, readOnly }: { initial?: ColorCard; onClose: () => void; onSave: (body: Record<string, unknown>) => void; saving: boolean; readOnly: boolean }) {
  const [brandKey, setBrandKey] = useState(initial?.brandKey ?? '');
  const [displayName, setDisplayName] = useState(initial?.displayName ?? '');
  const [colorCount, setColorCount] = useState(String(initial?.colorCount ?? ''));
  const [sourceUrl, setSourceUrl] = useState(initial?.sourceUrl ?? '');
  const [status, setStatus] = useState<CardStatus>(initial?.status ?? 'active');
  const [notes, setNotes] = useState(initial?.notes ?? '');
  const count = Number(colorCount);
  const valid = CARD_KEY_PATTERN.test(brandKey) && displayName.trim().length > 0 && Number.isInteger(count) && count >= 1 && count <= 10000;
  return <Modal title={initial ? '编辑色卡配置' : '新建色卡配置'} detail="品牌标识 用于稳定排序；色卡名称请使用“品牌-色卡数量”。" close={onClose} busy={saving}><div className="space-y-4 p-4 sm:p-5"><label className="block text-xs admin-muted">品牌标识<input value={brandKey} maxLength={80} disabled={readOnly || saving} onChange={(event) => setBrandKey(event.target.value)} placeholder="mard" className="mt-1 min-h-11 w-full border admin-final-surface px-3 text-sm" /></label>{brandKey && !CARD_KEY_PATTERN.test(brandKey) && <Notice tone="rose">品牌标识 必须以小写字母开头，只能包含小写字母、数字、点、连字符和下划线。</Notice>}<label className="block text-xs admin-muted">色卡名称<input value={displayName} maxLength={120} disabled={readOnly || saving} onChange={(event) => setDisplayName(event.target.value)} placeholder="Mard-291" className="mt-1 min-h-11 w-full border admin-final-surface px-3 text-sm" /></label><label className="block text-xs admin-muted">色卡数量<input value={colorCount} inputMode="numeric" disabled={readOnly || saving} onChange={(event) => setColorCount(event.target.value)} className="mt-1 min-h-11 w-full border admin-final-surface px-3 text-sm" /></label><div className="grid gap-4 sm:grid-cols-2"><label className="block text-xs admin-muted">状态<select value={status} disabled={readOnly || saving} onChange={(event) => setStatus(event.target.value as CardStatus)} className="mt-1 min-h-11 w-full border admin-final-surface px-3 text-sm">{CARD_STATUSES.map((item) => <option key={item} value={item}>{adminLabel(item)}</option>)}</select></label><label className="block text-xs admin-muted">公开来源<input value={sourceUrl} maxLength={2048} type="url" disabled={readOnly || saving} onChange={(event) => setSourceUrl(event.target.value)} placeholder="https://..." className="mt-1 min-h-11 w-full border admin-final-surface px-3 text-sm" /></label></div><label className="block text-xs admin-muted">备注<textarea value={notes} maxLength={4000} disabled={readOnly || saving} onChange={(event) => setNotes(event.target.value)} className="mt-1 min-h-28 w-full border admin-final-surface p-3 text-sm leading-6" /></label><div className="flex justify-end gap-2"><AdminButton type="button" data-editor-cancel onClick={onClose} className="min-h-11 border px-4 text-sm">取消</AdminButton><AdminButton type="button" disabled={!valid || readOnly || saving} onClick={() => onSave({ ...(initial ? { id: initial.id } : {}), brandKey: brandKey.trim(), displayName: displayName.trim(), colorCount: count, sourceUrl: sourceUrl.trim() || null, status, notes: notes.trim() })} className="flex min-h-11 items-center gap-2 bg-sky-400 px-4 text-sm font-medium disabled:opacity-40"><Save className="h-4 w-4" />保存</AdminButton></div></div></Modal>;
}

function SwatchEditor({ card, initial, onClose, onSave, saving, readOnly }: { card: ColorCard; initial?: ColorSwatch; onClose: () => void; onSave: (body: Record<string, unknown>) => void; saving: boolean; readOnly: boolean }) {
  const [colorCode, setColorCode] = useState(initial?.colorCode ?? '');
  const [displayName, setDisplayName] = useState(initial?.displayName ?? '');
  const [hex, setHex] = useState(initial?.hex ?? '#000000');
  const [rgb, setRgb] = useState(initial?.rgb ?? { r: 0, g: 0, b: 0 });
  const [sortOrder, setSortOrder] = useState(String(initial?.sortOrder ?? 0));
  const normalizedHex = hex.trim().toUpperCase();
  const sort = Number(sortOrder);
  const rgbValid = [rgb.r, rgb.g, rgb.b].every((value) => Number.isInteger(value) && value >= 0 && value <= 255);
  const valid = colorCode.trim().length > 0 && colorCode.trim().length <= 80 && HEX_PATTERN.test(normalizedHex) && rgbValid && Number.isInteger(sort) && sort >= 0 && sort <= 1000000;
  const setHexAndRgb = (value: string) => { const normalized = value.toUpperCase(); setHex(normalized); if (HEX_PATTERN.test(normalized)) setRgb({ r: Number.parseInt(normalized.slice(1, 3), 16), g: Number.parseInt(normalized.slice(3, 5), 16), b: Number.parseInt(normalized.slice(5, 7), 16) }); };
  return <Modal title={initial ? '编辑色号' : '新增色号'} detail={`${card.displayName} · 输入 HEX 会自动同步 RGB。`} close={onClose} busy={saving}><div className="space-y-4 p-4 sm:p-5"><div className="grid gap-4 sm:grid-cols-2"><label className="block text-xs admin-muted">色号<input value={colorCode} maxLength={80} disabled={readOnly || saving} onChange={(event) => setColorCode(event.target.value)} placeholder="A01" className="mt-1 min-h-11 w-full border admin-final-surface px-3 text-sm" /></label><label className="block text-xs admin-muted">名称<input value={displayName} maxLength={120} disabled={readOnly || saving} onChange={(event) => setDisplayName(event.target.value)} placeholder="樱花粉" className="mt-1 min-h-11 w-full border admin-final-surface px-3 text-sm" /></label></div><div className="grid gap-4 sm:grid-cols-[1fr_9rem]"><label className="block text-xs admin-muted">HEX<input value={hex} maxLength={7} disabled={readOnly || saving} onChange={(event) => setHexAndRgb(event.target.value)} placeholder="#RRGGBB" className="mt-1 min-h-11 w-full border admin-final-surface px-3 font-mono text-sm uppercase" /></label><span className="mt-5 h-11 border" style={{ backgroundColor: HEX_PATTERN.test(normalizedHex) ? normalizedHex : 'transparent' }} aria-label="色彩预览" /></div>{hex && !HEX_PATTERN.test(normalizedHex) && <Notice tone="rose">HEX 必须为 #RRGGBB，例如 #FF0088。</Notice>}<div className="grid grid-cols-3 gap-3">{(['r', 'g', 'b'] as const).map((channel) => <label key={channel} className="block text-xs uppercase admin-muted">{channel}<input type="number" min="0" max="255" value={rgb[channel]} disabled={readOnly || saving} onChange={(event) => setRgb((current) => ({ ...current, [channel]: Number(event.target.value) }))} className="mt-1 min-h-11 w-full border admin-final-surface px-3 text-sm" /></label>)}</div><label className="block text-xs admin-muted">排序<input type="number" min="0" max="1000000" value={sortOrder} disabled={readOnly || saving} onChange={(event) => setSortOrder(event.target.value)} className="mt-1 min-h-11 w-full border admin-final-surface px-3 text-sm" /></label><div className="flex justify-end gap-2"><AdminButton type="button" data-editor-cancel onClick={onClose} className="min-h-11 border px-4 text-sm">取消</AdminButton><AdminButton type="button" disabled={!valid || readOnly || saving} onClick={() => onSave({ ...(initial ? { id: initial.id } : {}), cardId: card.id, colorCode: colorCode.trim(), displayName: displayName.trim(), hex: normalizedHex, rgb, sortOrder: sort })} className="flex min-h-11 items-center gap-2 bg-sky-400 px-4 text-sm font-medium disabled:opacity-40"><Save className="h-4 w-4" />保存</AdminButton></div></div></Modal>;
}

function AssetEditor({ initial, onClose, onSave, saving, readOnly }: { initial?: StorageAsset; onClose: () => void; onSave: (body: Record<string, unknown>) => void; saving: boolean; readOnly: boolean }) {
  const [objectKey, setObjectKey] = useState(initial?.objectKey ?? ''); const [resourceType, setResourceType] = useState(initial?.resourceType ?? ''); const [contentType, setContentType] = useState(initial?.contentType ?? ''); const [byteCount, setByteCount] = useState(String(initial?.byteSize ?? 0)); const [ownerUid, setOwnerUid] = useState(initial?.ownerUid ?? ''); const [visibility, setVisibility] = useState<AssetVisibility>(initial?.visibility ?? 'private'); const [status, setStatus] = useState<AssetStatus>(initial?.status ?? 'active'); const [metadataRaw, setMetadataRaw] = useState(() => jsonDraftText(initial?.metadata));
  const parsedSize = Number(byteCount); let metadata: unknown = null; let metadataError = '';
  try { metadata = JSON.parse(metadataRaw); } catch { metadataError = '元数据必须是有效 JSON。'; }
  const valid = objectKey.trim().length > 0 && objectKey.trim().length <= 1000 && resourceType.trim().length > 0 && resourceType.trim().length <= 120 && Number.isInteger(parsedSize) && parsedSize >= 0 && !metadataError;
  return <Modal title={initial ? '编辑资源元数据' : '登记资源元数据'} detail="这里只维护 D1 中的资源索引，不会上传、读取或删除 R2 对象。" close={onClose} busy={saving}><div className="space-y-4 p-4 sm:p-5"><div className="grid gap-4 sm:grid-cols-2"><label className="block text-xs admin-muted">对象标识<input value={objectKey} maxLength={1000} disabled={readOnly || saving} onChange={(event) => setObjectKey(event.target.value)} className="mt-1 min-h-11 w-full border admin-final-surface px-3 text-sm" /></label><label className="block text-xs admin-muted">资源类型<input value={resourceType} maxLength={120} disabled={readOnly || saving} onChange={(event) => setResourceType(event.target.value)} placeholder="avatar / work / export" className="mt-1 min-h-11 w-full border admin-final-surface px-3 text-sm" /></label><label className="block text-xs admin-muted">MIME 类型<input value={contentType} maxLength={255} disabled={readOnly || saving} onChange={(event) => setContentType(event.target.value)} placeholder="image/png" className="mt-1 min-h-11 w-full border admin-final-surface px-3 text-sm" /></label><label className="block text-xs admin-muted">字节数<input type="number" min="0" value={byteCount} disabled={readOnly || saving} onChange={(event) => setByteCount(event.target.value)} className="mt-1 min-h-11 w-full border admin-final-surface px-3 text-sm" /></label><label className="block text-xs admin-muted">所属用户 UID<input value={ownerUid} maxLength={128} disabled={readOnly || saving} onChange={(event) => setOwnerUid(event.target.value)} className="mt-1 min-h-11 w-full border admin-final-surface px-3 text-sm" /></label><label className="block text-xs admin-muted">可见性<select value={visibility} disabled={readOnly || saving} onChange={(event) => setVisibility(event.target.value as AssetVisibility)} className="mt-1 min-h-11 w-full border admin-final-surface px-3 text-sm"><option value="private">{adminLabel('private')}</option><option value="public">{adminLabel('public')}</option><option value="restricted">{adminLabel('restricted')}</option></select></label></div><label className="block text-xs admin-muted">状态<select value={status} disabled={readOnly || saving} onChange={(event) => setStatus(event.target.value as AssetStatus)} className="mt-1 min-h-11 w-full border admin-final-surface px-3 text-sm"><option value="active">{adminLabel('active')}</option><option value="deleted">{adminLabel('deleted')}</option></select></label><label className="block text-xs admin-muted">元数据 JSON<textarea value={metadataRaw} disabled={readOnly || saving} onChange={(event) => setMetadataRaw(event.target.value)} spellCheck={false} className="mt-1 min-h-44 w-full border admin-final-surface p-3 font-mono text-xs leading-6" /></label>{metadataError && <Notice tone="rose">{metadataError}</Notice>}<div className="flex justify-end gap-2"><AdminButton type="button" data-editor-cancel onClick={onClose} className="min-h-11 border px-4 text-sm">取消</AdminButton><AdminButton type="button" disabled={!valid || readOnly || saving} onClick={() => onSave({ ...(initial ? { id: initial.id } : {}), objectKey: objectKey.trim(), resourceType: resourceType.trim(), contentType: contentType.trim() || null, byteSize: parsedSize, ownerUid: ownerUid.trim() || null, visibility, status, metadata })} className="flex min-h-11 items-center gap-2 bg-sky-400 px-4 text-sm font-medium disabled:opacity-40"><Save className="h-4 w-4" />保存</AdminButton></div></div></Modal>;
}

function ColorsAssetsPanel({ request }: { request: AdminRequest }) {
  const write = useContentWrite(request);
  const [tab, setTab] = useState<'cards' | 'swatches' | 'assets'>('cards'); const [cards, setCards] = useState<ColorCard[]>([]); const [cardsPage, setCardsPage] = useState(1); const [cardsTotal, setCardsTotal] = useState(0); const [cardsStatus, setCardsStatus] = useState<CardStatus | 'all'>('all'); const [cardsSearch, setCardsSearch] = useState(''); const deferredSearch = useDeferredValue(cardsSearch); const [selectedCard, setSelectedCard] = useState<ColorCard | null>(null); const [swatches, setSwatches] = useState<ColorSwatch[]>([]); const [swatchesPage, setSwatchesPage] = useState(1); const [swatchesTotal, setSwatchesTotal] = useState(0); const [assets, setAssets] = useState<StorageAsset[]>([]); const [assetsPage, setAssetsPage] = useState(1); const [assetsTotal, setAssetsTotal] = useState(0); const [assetOwner, setAssetOwner] = useState(''); const [assetType, setAssetType] = useState(''); const [assetStatus, setAssetStatus] = useState<AssetStatus | 'all'>('all'); const deferredOwner = useDeferredValue(assetOwner); const deferredAssetType = useDeferredValue(assetType); const [loading, setLoading] = useState(false); const saving = write.busy; const [readOnly, setReadOnly] = useState(false); const [error, setError] = useState(''); const [cardEditor, setCardEditor] = useState<ColorCard | 'new' | null>(null); const [swatchEditor, setSwatchEditor] = useState<ColorSwatch | 'new' | null>(null); const [assetEditor, setAssetEditor] = useState<StorageAsset | 'new' | null>(null); const requestVersion = useRef(0); const [loadedPages, setLoadedPages] = useState<Record<string, number>>({});
  const fail = (status: number, message: string | undefined, fallback: string) => { setReadOnly(true); setError(fallback + (status === 403 ? '被服务端拒绝（403）：' : '：') + (message ?? '请重试。') + ' 当前结果未更新，已有内容仅供参考，请刷新核对。'); };
  const loadCards = useCallback(async () => { const version = ++requestVersion.current; const ticket = write.beginRead('/api/admin/color-cards'); setLoading(true); setError(''); try { const result = await request<Paged<ColorCard>>(`/api/admin/color-cards${query({ page: cardsPage, limit: PAGE_SIZE, status: cardsStatus === 'all' ? null : cardsStatus, search: deferredSearch })}`); if (version !== requestVersion.current) return; if (!result.ok) { fail(result.status, result.error, '色卡配置加载失败。'); return; } if (!result.data || !Array.isArray(result.data.items) || !Number.isFinite(result.data.total)) { fail(result.status, '返回的数据结构不完整。', '列表读取失败'); return; } if (cardsPage > adminPageCount(result.data.total)) { setCardsPage(adminPageCount(result.data.total)); return; } setLoadedPages(value => ({ ...value, cards: cardsPage })); setCards(result.data?.items ?? []); setCardsTotal(result.data?.total ?? 0); setReadOnly(false); write.readSucceeded(ticket); } catch (caught) { if (version === requestVersion.current) { setReadOnly(true); setError(getError(caught, '色卡配置加载失败。')); } } finally { if (version === requestVersion.current) setLoading(false); } }, [cardsPage, cardsStatus, deferredSearch, request]);
  const loadSwatches = useCallback(async () => { if (!selectedCard) return; const version = ++requestVersion.current; const ticket = write.beginRead('/api/admin/color-swatches'); setLoading(true); setError(''); try { const result = await request<Paged<ColorSwatch>>(`/api/admin/color-swatches${query({ cardId: selectedCard.id, page: swatchesPage, limit: PAGE_SIZE })}`); if (version !== requestVersion.current) return; if (!result.ok) { fail(result.status, result.error, '色号加载失败。'); return; } if (!result.data || !Array.isArray(result.data.items) || !Number.isFinite(result.data.total)) { fail(result.status, '返回的数据结构不完整。', '列表读取失败'); return; } if (swatchesPage > adminPageCount(result.data.total)) { setSwatchesPage(adminPageCount(result.data.total)); return; } setLoadedPages(value => ({ ...value, swatches: swatchesPage })); setSwatches(result.data?.items ?? []); setSwatchesTotal(result.data?.total ?? 0); setReadOnly(false); write.readSucceeded(ticket); } catch (caught) { if (version === requestVersion.current) { setReadOnly(true); setError(getError(caught, '色号加载失败。')); } } finally { if (version === requestVersion.current) setLoading(false); } }, [request, selectedCard, swatchesPage]);
  const loadAssets = useCallback(async () => { const version = ++requestVersion.current; const ticket = write.beginRead('/api/admin/storage-assets'); setLoading(true); setError(''); try { const result = await request<Paged<StorageAsset>>(`/api/admin/storage-assets${query({ page: assetsPage, limit: PAGE_SIZE, ownerUid: deferredOwner, resourceType: deferredAssetType, status: assetStatus === 'all' ? null : assetStatus })}`); if (version !== requestVersion.current) return; if (!result.ok) { fail(result.status, result.error, '资源元数据加载失败。'); return; } if (!result.data || !Array.isArray(result.data.items) || !Number.isFinite(result.data.total)) { fail(result.status, '返回的数据结构不完整。', '列表读取失败'); return; } if (assetsPage > adminPageCount(result.data.total)) { setAssetsPage(adminPageCount(result.data.total)); return; } setLoadedPages(value => ({ ...value, assets: assetsPage })); setAssets(result.data?.items ?? []); setAssetsTotal(result.data?.total ?? 0); setReadOnly(false); write.readSucceeded(ticket); } catch (caught) { if (version === requestVersion.current) { setReadOnly(true); setError(getError(caught, '资源元数据加载失败。')); } } finally { if (version === requestVersion.current) setLoading(false); } }, [assetStatus, assetsPage, deferredAssetType, deferredOwner, request]);
  useEffect(() => { if (tab === 'cards') void loadCards(); if (tab === 'swatches' && selectedCard) void loadSwatches(); if (tab === 'assets') void loadAssets(); return () => { requestVersion.current++; }; }, [loadAssets, loadCards, loadSwatches, selectedCard, tab]);
  const reload = () => { if (tab === 'cards') void loadCards(); else if (tab === 'swatches') void loadSwatches(); else void loadAssets(); };
  const save = (path: string, method: 'POST' | 'PUT', body: Record<string, unknown>, label: string, close: () => void) => {
    const before = path.endsWith('color-cards') ? cardEditor === 'new' ? undefined : cardEditor : path.endsWith('color-swatches') ? swatchEditor === 'new' ? undefined : swatchEditor : assetEditor === 'new' ? undefined : assetEditor;
    write.review({ path, method, body, before, title: label, object: String(body.displayName ?? body.colorCode ?? body.objectKey ?? body.id ?? '新元数据'), impact: path.endsWith('storage-assets') ? '仅登记/修改后台资源索引，不上传、读取或删除R2实际对象。' : '只维护此色卡/色号元数据，保留原品牌排序/校验规则，不修改图纸或转换算法。', done: () => { close(); reload(); } });
  };
  const remove = (path: string, itemLabel: string) => {
    const id = new URL(path, window.location.origin).searchParams.get('id');
    const before = [...cards, ...swatches, ...assets].find(item => item.id === id);
    write.review({ path, method: 'DELETE', before, title: '删除后台元数据', object: itemLabel, impact: '删除此后台元数据记录及服务端定义的关联处理，不可由此界面恢复；不删除R2实际对象。', done: reload });
  };
  const activeRows = tab === 'cards' ? cards : tab === 'swatches' ? swatches : assets;
  return <section><PanelHeading eyebrow="品牌色卡与文件索引" title="色卡与资源" description={tab === 'assets' ? '仅维护资源元数据索引，不会直接操作 R2 文件。' : '品牌优先级由 品牌标识 决定，同品牌按色卡数量升序排列。'} refresh={reload} loading={loading} readOnly={readOnly || loading || saving} create={tab === 'cards' ? () => setCardEditor('new') : tab === 'swatches' && selectedCard ? () => setSwatchEditor('new') : tab === 'assets' ? () => setAssetEditor('new') : undefined} createLabel={tab === 'cards' ? '新建色卡' : tab === 'swatches' ? '新增色号' : '登记资源'} />{error && <div className="mt-5"><Notice tone={readOnly ? 'rose' : 'amber'}>{error}</Notice></div>}<div className="mt-5 flex gap-2 overflow-x-auto border-b">{([{ id: 'cards', label: '色卡配置', icon: Palette }, { id: 'swatches', label: '色号', icon: Layers3 }, { id: 'assets', label: '资源元数据', icon: FolderCog }] as const).map((item) => { const Icon = item.icon; return <AdminButton key={item.id} type="button" aria-pressed={tab === item.id} onClick={() => setTab(item.id)} className={`flex min-h-11 shrink-0 items-center gap-2 px-4 text-sm ${tab === item.id ? 'border-b-2 admin-final-active' : 'admin-muted'}`}><Icon className="h-4 w-4" />{item.label}</AdminButton>; })}</div>{tab === 'cards' && <><div className="mt-4 grid gap-3 lg:grid-cols-[minmax(0,1fr)_11rem]"><label className="relative block"><Search className="absolute left-3 top-3.5 h-4 w-4 admin-muted" /><input aria-label="搜索色卡" value={cardsSearch} onChange={(event) => { setCardsSearch(event.target.value); setCardsPage(1); }} placeholder="按品牌或色卡名称搜索" className="min-h-11 w-full border admin-final-surface py-2 pl-9 pr-3 text-sm placeholder:text-slate-600" /></label><select aria-label="色卡状态筛选" value={cardsStatus} onChange={(event) => { setCardsStatus(event.target.value as CardStatus | 'all'); setCardsPage(1); }} className="min-h-11 border admin-final-surface px-3 text-sm"><option value="all">全部状态</option>{CARD_STATUSES.map((item) => <option key={item} value={item}>{adminLabel(item)}</option>)}</select></div><div className="mt-5">{loading ? <Loading /> : cards.length ? <><div className="hidden overflow-x-auto border md:block"><table className="w-full min-w-[900px] text-left text-sm"><thead className="admin-final-surface text-xs admin-muted"><tr><th className="px-4 py-3">名称</th><th className="px-4 py-3">品牌标识</th><th className="px-4 py-3">标称 / 已录入</th><th className="px-4 py-3">状态</th><th className="px-4 py-3 text-right">操作</th></tr></thead><tbody>{cards.map((card) => <tr key={card.id} className="border-t"><td className="px-4 py-3"><p className="font-medium">{card.displayName}</p><p className="mt-1 max-w-sm truncate text-xs admin-muted">{card.sourceUrl ?? (card.notes || '-')}</p></td><td className="px-4 py-3 font-mono">{card.brandKey}</td><td className="px-4 py-3 tabular-nums">{card.colorCount} / {card.swatchCount}</td><td className="px-4 py-3 admin-muted">{adminLabel(card.status)}</td><td className="px-4 py-3"><div className="flex justify-end gap-1"><AdminButton type="button" onClick={() => { setSelectedCard(card); setSwatchesPage(1); setTab('swatches'); }} className="min-h-11 px-3 text-emerald-200">色号</AdminButton><AdminButton type="button" onClick={() => setCardEditor(card)} disabled={readOnly || loading || saving} className="grid h-11 w-11 place-items-center disabled:opacity-40" title="编辑色卡" aria-label="编辑色卡"><Pencil className="h-4 w-4" /></AdminButton><AdminButton type="button" onClick={() => void remove(`/api/admin/color-cards${query({ id: card.id })}`, `色卡“${card.displayName}”`)} disabled={readOnly || loading || saving} className="grid h-11 w-11 place-items-center disabled:opacity-40" title="删除色卡" aria-label="删除色卡"><Trash2 className="h-4 w-4" /></AdminButton></div></td></tr>)}</tbody></table></div><div className="space-y-2 md:hidden">{cards.map((card) => <article key={card.id} className="border admin-final-surface p-3"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><p className="truncate font-medium">{card.displayName}</p><p className="mt-1 font-mono text-xs">{card.brandKey}</p></div><span className="text-xs admin-muted">{adminLabel(card.status)}</span></div><p className="mt-3 text-xs admin-muted">色号 {card.swatchCount} / 标称 {card.colorCount}</p><div className="mt-3 grid grid-cols-3 gap-2"><AdminButton type="button" onClick={() => { setSelectedCard(card); setSwatchesPage(1); setTab('swatches'); }} className="min-h-11 border border-emerald-400/40 text-sm text-emerald-200">色号</AdminButton><AdminButton type="button" disabled={readOnly || loading || saving} onClick={() => setCardEditor(card)} className="min-h-11 border text-sm disabled:opacity-40">编辑</AdminButton><AdminButton type="button" disabled={readOnly || loading || saving} onClick={() => void remove(`/api/admin/color-cards${query({ id: card.id })}`, `色卡“${card.displayName}”`)} className="min-h-11 border text-sm disabled:opacity-40">删除</AdminButton></div></article>)}</div><Pager busy={loading || saving || Boolean(error)} page={loadedPages.cards ?? 1} total={cardsTotal} onChange={setCardsPage} /></> : <Empty error={error}>暂无符合条件的色卡配置。</Empty>}</div></>}{tab === 'swatches' && <><div className="mt-4 flex min-h-11 items-center justify-between gap-3 border admin-final-surface px-3"><div className="min-w-0"><p className="truncate text-sm">{selectedCard ? selectedCard.displayName : '请先在色卡配置中选择一个色卡'}</p><p className="mt-1 text-xs admin-muted">按排序值和色号稳定排序。</p></div>{selectedCard && <AdminButton type="button" onClick={() => setTab('cards')} className="shrink-0 text-sm">更换色卡</AdminButton>}</div><div className="mt-5">{!selectedCard ? <Empty error={error}>选择色卡后才能管理该色卡的色号。</Empty> : loading ? <Loading /> : swatches.length ? <><div className="hidden overflow-x-auto border md:block"><table className="w-full min-w-[800px] text-left text-sm"><thead className="admin-final-surface text-xs admin-muted"><tr><th className="px-4 py-3">预览</th><th className="px-4 py-3">色号 / 名称</th><th className="px-4 py-3">HEX</th><th className="px-4 py-3">RGB</th><th className="px-4 py-3">排序</th><th className="px-4 py-3 text-right">操作</th></tr></thead><tbody>{swatches.map((swatch) => <tr key={swatch.id} className="border-t"><td className="px-4 py-3"><span className="block h-8 w-8 border border-white/15" style={{ backgroundColor: swatch.hex }} /></td><td className="px-4 py-3"><p className="font-mono">{swatch.colorCode}</p><p className="mt-1 text-xs admin-muted">{swatch.displayName || '-'}</p></td><td className="px-4 py-3 font-mono">{swatch.hex}</td><td className="px-4 py-3 tabular-nums admin-muted">{swatch.rgb.r}, {swatch.rgb.g}, {swatch.rgb.b}</td><td className="px-4 py-3 tabular-nums admin-muted">{swatch.sortOrder}</td><td className="px-4 py-3"><div className="flex justify-end gap-1"><AdminButton type="button" disabled={readOnly || loading || saving} onClick={() => setSwatchEditor(swatch)} className="grid h-11 w-11 place-items-center disabled:opacity-40" title="编辑色号" aria-label="编辑色号"><Pencil className="h-4 w-4" /></AdminButton><AdminButton type="button" disabled={readOnly || loading || saving} onClick={() => void remove(`/api/admin/color-swatches${query({ id: swatch.id })}`, `色号“${swatch.colorCode}”`)} className="grid h-11 w-11 place-items-center disabled:opacity-40" title="删除色号" aria-label="删除色号"><Trash2 className="h-4 w-4" /></AdminButton></div></td></tr>)}</tbody></table></div><div className="grid gap-2 sm:grid-cols-2 md:hidden">{swatches.map((swatch) => <article key={swatch.id} className="flex gap-3 border admin-final-surface p-3"><span className="h-11 w-11 shrink-0 border border-white/15" style={{ backgroundColor: swatch.hex }} /><div className="min-w-0 flex-1"><p className="font-mono text-sm">{swatch.colorCode}</p><p className="truncate text-xs admin-muted">{swatch.displayName || swatch.hex}</p><p className="mt-1 text-xs admin-muted">RGB {swatch.rgb.r}, {swatch.rgb.g}, {swatch.rgb.b}</p><div className="mt-2 flex gap-2"><AdminButton type="button" disabled={readOnly || loading || saving} onClick={() => setSwatchEditor(swatch)} className="min-h-10 flex-1 border text-sm disabled:opacity-40">编辑</AdminButton><AdminButton type="button" disabled={readOnly || loading || saving} onClick={() => void remove(`/api/admin/color-swatches${query({ id: swatch.id })}`, `色号“${swatch.colorCode}”`)} className="min-h-10 flex-1 border text-sm disabled:opacity-40">删除</AdminButton></div></div></article>)}</div><Pager busy={loading || saving || Boolean(error)} page={loadedPages.swatches ?? 1} total={swatchesTotal} onChange={setSwatchesPage} /></> : <Empty error={error}>该色卡尚未录入色号。</Empty>}</div></>}{tab === 'assets' && <><div className="mt-4 grid gap-3 lg:grid-cols-3"><input aria-label="所属用户 UID 筛选" value={assetOwner} maxLength={128} onChange={(event) => { setAssetOwner(event.target.value); setAssetsPage(1); }} placeholder="按所属用户 UID 筛选" className="min-h-11 border admin-final-surface px-3 text-sm placeholder:text-slate-600" /><input aria-label="资源类型筛选" value={assetType} maxLength={120} onChange={(event) => { setAssetType(event.target.value); setAssetsPage(1); }} placeholder="按资源类型精确筛选" className="min-h-11 border admin-final-surface px-3 text-sm placeholder:text-slate-600" /><select aria-label="资源状态筛选" value={assetStatus} onChange={(event) => { setAssetStatus(event.target.value as AssetStatus | 'all'); setAssetsPage(1); }} className="min-h-11 border admin-final-surface px-3 text-sm"><option value="all">全部状态</option><option value="active">{adminLabel('active')}</option><option value="deleted">{adminLabel('deleted')}</option></select></div><div className="mt-5">{loading ? <Loading /> : assets.length ? <><div className="hidden overflow-x-auto border md:block"><table className="w-full min-w-[980px] text-left text-sm"><thead className="admin-final-surface text-xs admin-muted"><tr><th className="px-4 py-3">对象标识</th><th className="px-4 py-3">类型 / 大小</th><th className="px-4 py-3">可见性</th><th className="px-4 py-3">状态</th><th className="px-4 py-3 text-right">操作</th></tr></thead><tbody>{assets.map((asset) => <tr key={asset.id} className="border-t"><td className="max-w-sm px-4 py-3"><p className="truncate font-mono text-xs">{asset.objectKey}</p><p className="mt-1 truncate text-xs admin-muted">{asset.ownerUid ?? '无所属用户'}</p></td><td className="px-4 py-3"><p className="">{asset.resourceType}</p><p className="mt-1 text-xs admin-muted">{asset.contentType ?? '-'} · {byteSize(asset.byteSize)}</p></td><td className="px-4 py-3">{adminLabel(asset.visibility)}</td><td className="px-4 py-3 admin-muted">{adminLabel(asset.status)}</td><td className="px-4 py-3"><div className="flex justify-end gap-1"><AdminButton type="button" disabled={readOnly || loading || saving} onClick={() => setAssetEditor(asset)} className="grid h-11 w-11 place-items-center disabled:opacity-40" title="编辑资源元数据" aria-label="编辑资源元数据"><Pencil className="h-4 w-4" /></AdminButton><AdminButton type="button" disabled={readOnly || loading || saving} onClick={() => void remove(`/api/admin/storage-assets${query({ id: asset.id })}`, `资源“${asset.objectKey}”`)} className="grid h-11 w-11 place-items-center disabled:opacity-40" title="删除资源元数据" aria-label="删除资源元数据"><Trash2 className="h-4 w-4" /></AdminButton></div></td></tr>)}</tbody></table></div><div className="space-y-2 md:hidden">{assets.map((asset) => <article key={asset.id} className="border admin-final-surface p-3"><p className="truncate font-mono text-xs">{asset.objectKey}</p><p className="mt-2 text-sm">{asset.resourceType} · {byteSize(asset.byteSize)}</p><p className="mt-1 text-xs admin-muted">{adminLabel(asset.visibility)} · {adminLabel(asset.status)}</p><div className="mt-3 grid grid-cols-2 gap-2"><AdminButton type="button" disabled={readOnly || loading || saving} onClick={() => setAssetEditor(asset)} className="min-h-11 border text-sm disabled:opacity-40">编辑元数据</AdminButton><AdminButton type="button" disabled={readOnly || loading || saving} onClick={() => void remove(`/api/admin/storage-assets${query({ id: asset.id })}`, `资源“${asset.objectKey}”`)} className="min-h-11 border text-sm disabled:opacity-40">删除元数据</AdminButton></div></article>)}</div><Pager busy={loading || saving || Boolean(error)} page={loadedPages.assets ?? 1} total={assetsTotal} onChange={setAssetsPage} /></> : <Empty error={error}>暂无符合条件的资源元数据。</Empty>}</div></>}{cardEditor && <ColorCardEditor initial={cardEditor === 'new' ? undefined : cardEditor} onClose={() => setCardEditor(null)} onSave={(body) => void save('/api/admin/color-cards', cardEditor === 'new' ? 'POST' : 'PUT', body, cardEditor === 'new' ? '创建色卡' : '保存色卡', () => setCardEditor(null))} saving={saving} readOnly={readOnly || loading || saving} />}{swatchEditor && selectedCard && <SwatchEditor card={selectedCard} initial={swatchEditor === 'new' ? undefined : swatchEditor} onClose={() => setSwatchEditor(null)} onSave={(body) => void save('/api/admin/color-swatches', swatchEditor === 'new' ? 'POST' : 'PUT', body, swatchEditor === 'new' ? '创建色号' : '保存色号', () => setSwatchEditor(null))} saving={saving} readOnly={readOnly || loading || saving} />}{assetEditor && <AssetEditor initial={assetEditor === 'new' ? undefined : assetEditor} onClose={() => setAssetEditor(null)} onSave={(body) => void save('/api/admin/storage-assets', assetEditor === 'new' ? 'POST' : 'PUT', body, assetEditor === 'new' ? '登记资源元数据' : '保存资源元数据', () => setAssetEditor(null))} saving={saving} readOnly={readOnly || loading || saving} />}{write.success && <p className="admin-success-message" role="status">{write.success}</p>}{write.confirmation}</section>;
}

function ModerationEditor({ content, onClose, onSave, saving, readOnly }: { content: CommunityContent; onClose: () => void; onSave: (body: Record<string, unknown>) => void; saving: boolean; readOnly: boolean }) {
  const [action, setAction] = useState<ModerationAction>('approve'); const [reason, setReason] = useState(''); const [metadataRaw, setMetadataRaw] = useState('{}'); let metadata: unknown = null; let metadataError = '';
  try { metadata = JSON.parse(metadataRaw); } catch { metadataError = '附加数据必须是有效 JSON。'; }
  const sensitive = action === 'hide' || action === 'remove';
  return <Modal title="新增内容审核动作" detail="缺少正文/图片证据；此处只写独立审核记录，不声称实际下线或完整复核。" close={onClose} busy={saving}><div className="space-y-4 p-4 sm:p-5"><div className="border admin-final-surface p-3 text-sm"><p className="font-medium">{content.title || content.id}</p><p className="mt-1 font-mono text-xs admin-muted">{adminLabel(content.entityType)}:{content.id}</p></div><label className="block text-xs admin-muted">动作<select value={action} disabled={readOnly || saving} onChange={(event) => setAction(event.target.value as ModerationAction)} className="mt-1 min-h-11 w-full border admin-final-surface px-3 text-sm">{MODERATION_ACTIONS.map((item) => <option key={item} value={item}>{adminLabel(item)}</option>)}</select></label>{sensitive && <Notice tone="rose">隐藏 / 移除是敏感审核动作，提交前会再次确认。</Notice>}<label className="block text-xs admin-muted">原因<textarea value={reason} maxLength={1000} disabled={readOnly || saving} onChange={(event) => setReason(event.target.value)} className="mt-1 min-h-28 w-full border admin-final-surface p-3 text-sm leading-6" /></label><label className="block text-xs admin-muted">附加数据 JSON<textarea value={metadataRaw} disabled={readOnly || saving} onChange={(event) => setMetadataRaw(event.target.value)} spellCheck={false} className="mt-1 min-h-36 w-full border admin-final-surface p-3 font-mono text-xs leading-6" /></label>{metadataError && <Notice tone="rose">{metadataError}</Notice>}<div className="flex justify-end gap-2"><AdminButton type="button" data-editor-cancel onClick={onClose} className="min-h-11 border px-4 text-sm">取消</AdminButton><AdminButton type="button" disabled={readOnly || saving || Boolean(metadataError)} onClick={() => onSave({ entityType: content.entityType, entityId: content.id, action, reason: reason.trim(), metadata })} className="flex min-h-11 items-center gap-2 bg-sky-400 px-4 text-sm font-medium disabled:opacity-40"><ClipboardCheck className="h-4 w-4" />记录审核</AdminButton></div></div></Modal>;
}

function ReportDetail({ report, onClose, update, saving, readOnly }: { report: ContentReport; onClose: () => void; update: (status: ReportStatus) => void; saving: boolean; readOnly: boolean }) {
  const [status,setStatus]=useState<ReportStatus>(report.status);
  return <Modal title="举报详情" detail="只读取现有举报摘要；状态选择是草稿，复核后才提交。" close={onClose} busy={saving}><dl className="admin-detail-facts"><div><dt>内容</dt><dd>{adminLabel(report.entityType)}:{report.entityId}</dd></div><div><dt>举报人</dt><dd>{report.reporterUid??'未提供'}</dd></div><div><dt>原因</dt><dd>{report.reasonCode}</dd></div><div><dt>时间</dt><dd>{time(report.createdAt)}</dd></div></dl><p>{report.description||'没有提供说明'}</p><label>拟提交处理状态<select data-report-status value={status} disabled={saving||readOnly} onChange={e=>setStatus(e.target.value as ReportStatus)}>{REPORT_STATUSES.map(value=><option key={value} value={value}>{adminLabel(value)}</option>)}</select></label><AdminButton disabled={saving||readOnly||status===report.status} onClick={()=>update(status)}>复核状态并提交</AdminButton></Modal>;
}

function CommunityPanel({ request }: { request: AdminRequest }) {
  const write = useContentWrite(request);
  const [tab, setTab] = useState<'content' | 'reports' | 'actions'>('content'); const [contentType, setContentType] = useState<ContentType>('work'); const [content, setContent] = useState<CommunityContent[]>([]); const [contentTotal, setContentTotal] = useState(0); const [contentPage, setContentPage] = useState(1); const [warnings, setWarnings] = useState<string[]>([]); const [reports, setReports] = useState<ContentReport[]>([]); const [reportsTotal, setReportsTotal] = useState(0); const [reportsPage, setReportsPage] = useState(1); const [reportStatus, setReportStatus] = useState<ReportStatus | 'all'>('all'); const [reportType, setReportType] = useState<ContentType | 'all'>('all'); const [actions, setActions] = useState<ModerationRecord[]>([]); const [actionsTotal, setActionsTotal] = useState(0); const [actionsPage, setActionsPage] = useState(1); const [actionEntityType, setActionEntityType] = useState<ContentType | 'all'>('all'); const [actionEntityId, setActionEntityId] = useState(''); const deferredActionId = useDeferredValue(actionEntityId); const [loading, setLoading] = useState(false); const saving = write.busy; const [readOnly, setReadOnly] = useState(false); const [error, setError] = useState(''); const [moderating, setModerating] = useState<CommunityContent | null>(null); const [reportDetail, setReportDetail] = useState<ContentReport | null>(null); const requestVersion = useRef(0); const [loadedPages, setLoadedPages] = useState<Record<string, number>>({});
  const fail = (status: number, message: string | undefined, fallback: string) => { setReadOnly(true); setError(fallback + (status === 403 ? '被服务端拒绝（403）：' : '：') + (message ?? '请重试。') + ' 当前结果未更新，已有内容仅供参考，请刷新核对。'); };
  const loadContent = useCallback(async () => { const version = ++requestVersion.current; const ticket = write.beginRead('/api/admin/community-content'); setLoading(true); setError(''); try { const result = await request<Paged<CommunityContent>>(`/api/admin/community-content${query({ type: contentType, page: contentPage, limit: PAGE_SIZE })}`); if (version !== requestVersion.current) return; if (!result.ok) { fail(result.status, result.error, '社区内容加载失败。'); return; } if (!result.data || !Array.isArray(result.data.items) || !Number.isFinite(result.data.total)) { fail(result.status, '返回的数据结构不完整。', '列表读取失败'); return; } if (contentPage > adminPageCount(result.data.total)) { setContentPage(adminPageCount(result.data.total)); return; } setLoadedPages(value => ({ ...value, content: contentPage })); setContent(result.data?.items ?? []); setContentTotal(result.data?.total ?? 0); setWarnings(result.data?.warnings ?? []); setReadOnly(false); write.readSucceeded(ticket); } catch (caught) { if (version === requestVersion.current) { setReadOnly(true); setError(getError(caught, '社区内容加载失败。')); } } finally { if (version === requestVersion.current) setLoading(false); } }, [contentPage, contentType, request]);
  const loadReports = useCallback(async () => { const version = ++requestVersion.current; const ticket = write.beginRead('/api/admin/reports'); setLoading(true); setError(''); try { const result = await request<Paged<ContentReport>>(`/api/admin/reports${query({ page: reportsPage, limit: PAGE_SIZE, status: reportStatus === 'all' ? null : reportStatus, entityType: reportType === 'all' ? null : reportType })}`); if (version !== requestVersion.current) return; if (!result.ok) { fail(result.status, result.error, '举报列表加载失败。'); return; } if (!result.data || !Array.isArray(result.data.items) || !Number.isFinite(result.data.total)) { fail(result.status, '返回的数据结构不完整。', '列表读取失败'); return; } if (reportsPage > adminPageCount(result.data.total)) { setReportsPage(adminPageCount(result.data.total)); return; } setLoadedPages(value => ({ ...value, reports: reportsPage })); setReports(result.data?.items ?? []); setReportsTotal(result.data?.total ?? 0); setReadOnly(false); write.readSucceeded(ticket); } catch (caught) { if (version === requestVersion.current) { setReadOnly(true); setError(getError(caught, '举报列表加载失败。')); } } finally { if (version === requestVersion.current) setLoading(false); } }, [reportStatus, reportType, reportsPage, request]);
  const loadActions = useCallback(async () => { const version = ++requestVersion.current; const ticket = write.beginRead('/api/admin/content-moderation'); setLoading(true); setError(''); try { const result = await request<Paged<ModerationRecord>>(`/api/admin/content-moderation${query({ page: actionsPage, limit: PAGE_SIZE, entityType: actionEntityType === 'all' ? null : actionEntityType, entityId: deferredActionId })}`); if (version !== requestVersion.current) return; if (!result.ok) { fail(result.status, result.error, '审核记录加载失败。'); return; } if (!result.data || !Array.isArray(result.data.items) || !Number.isFinite(result.data.total)) { fail(result.status, '返回的数据结构不完整。', '列表读取失败'); return; } if (actionsPage > adminPageCount(result.data.total)) { setActionsPage(adminPageCount(result.data.total)); return; } setLoadedPages(value => ({ ...value, actions: actionsPage })); setActions(result.data?.items ?? []); setActionsTotal(result.data?.total ?? 0); setReadOnly(false); write.readSucceeded(ticket); } catch (caught) { if (version === requestVersion.current) { setReadOnly(true); setError(getError(caught, '审核记录加载失败。')); } } finally { if (version === requestVersion.current) setLoading(false); } }, [actionEntityType, actionsPage, deferredActionId, request]);
  useEffect(() => { if (tab === 'content') void loadContent(); if (tab === 'reports') void loadReports(); if (tab === 'actions') void loadActions(); return () => { requestVersion.current++; }; }, [loadActions, loadContent, loadReports, tab]);
  const reload = () => { if (tab === 'content') void loadContent(); else if (tab === 'reports') void loadReports(); else void loadActions(); };
  const createAction = (body: Record<string, unknown>) => write.review({
    path: '/api/admin/content-moderation', method: 'POST', body, before: moderating, title: '复核内容审核记录', object: String(body.entityType) + ':' + String(body.entityId),
    impact: '仅追加既有独立审核记录。当前接口缺正文/图片证据；不声称已查看完整内容或实际前台下线，不直接改旧作品/帖子/评论表。',
    done: async () => { setModerating(null); await loadContent(); }
  });
  const updateReport = (report: ContentReport, status: ReportStatus) => {
    if (status === report.status) return;
    write.review({ path: '/api/admin/reports', method: 'PUT', body: { id: report.id, status }, before: report, title: '复核举报状态', object: report.entityType + ':' + report.entityId + ' · 举报' + report.id, impact: '仅更新这条举报处理状态及服务端处理记录，不自动改变内容或其它举报。', done: async () => { setReportDetail(null); await loadReports(); } });
  };
  return <section><div className="admin-final-notice" role="status">证据不足：当前列表接口只提供摘要，未提供正文/图片或完整证据。不能伪造预览；下方保留原审核/举报功能，仅追加或修改既有记录，不冒充真实下线。</div><PanelHeading eyebrow="内容审核与举报处理" title="社区内容" description="审核操作只追加独立审核记录，不直接更改既有作品、帖子或评论表。" refresh={reload} loading={loading} readOnly={readOnly || loading || saving} />{error && <div className="mt-5"><Notice tone={readOnly ? 'rose' : 'amber'}>{error}</Notice></div>}<div className="mt-5 flex gap-2 overflow-x-auto border-b">{([{ id: 'content', label: '社区内容', icon: Eye }, { id: 'reports', label: '举报处理', icon: Flag }, { id: 'actions', label: '审核记录', icon: ClipboardCheck }] as const).map((item) => { const Icon = item.icon; return <AdminButton key={item.id} type="button" aria-pressed={tab === item.id} onClick={() => setTab(item.id)} className={`flex min-h-11 shrink-0 items-center gap-2 px-4 text-sm ${tab === item.id ? 'border-b-2 admin-final-active' : 'admin-muted'}`}><Icon className="h-4 w-4" />{item.label}</AdminButton>; })}</div>{tab === 'content' && <><div className="mt-4 flex gap-2 overflow-x-auto">{(['work', 'post', 'comment'] as const).map((item) => <AdminButton key={item} type="button" aria-pressed={contentType === item} onClick={() => { setContentType(item); setContentPage(1); }} className={`min-h-10 shrink-0 border px-3 text-sm ${contentType === item ? 'admin-final-active' : 'admin-muted'}`}>{item === 'work' ? '图纸作品' : item === 'post' ? '社区帖子' : '评论'}</AdminButton>)}</div>{warnings.length > 0 && <div className="mt-4 space-y-2">{warnings.map((warning) => <div key={warning}><Notice>{warning}</Notice></div>)}</div>}<div className="mt-5">{loading ? <Loading /> : content.length ? <><div className="hidden overflow-x-auto border md:block"><table className="w-full min-w-[940px] text-left text-sm"><thead className="admin-final-surface text-xs admin-muted"><tr><th className="px-4 py-3">内容</th><th className="px-4 py-3">作者</th><th className="px-4 py-3">内容状态</th><th className="px-4 py-3">最新审核</th><th className="px-4 py-3 text-right">操作</th></tr></thead><tbody>{content.map((item) => <tr key={item.id} className="border-t"><td className="max-w-md px-4 py-3"><p className="truncate font-medium">{item.title || item.id}</p><p className="mt-1 font-mono text-xs admin-muted">{item.id}</p></td><td className="px-4 py-3 font-mono text-xs">{item.authorUid ?? '-'}</td><td className="px-4 py-3 admin-muted">{adminLabel(item.status)}</td><td className="px-4 py-3"><p className="">{item.moderation ? adminLabel(item.moderation.action) : '未审核'}</p><p className="mt-1 text-xs admin-muted">{item.moderation ? time(item.moderation.createdAt) : '-'}</p></td><td className="px-4 py-3 text-right"><AdminButton type="button" disabled={readOnly || loading || saving} onClick={() => setModerating(item)} className="min-h-11 px-3 disabled:opacity-40">审核</AdminButton></td></tr>)}</tbody></table></div><div className="space-y-2 md:hidden">{content.map((item) => <article key={item.id} className="border admin-final-surface p-3"><p className="truncate font-medium">{item.title || item.id}</p><p className="mt-1 truncate font-mono text-xs admin-muted">{item.id}</p><div className="mt-3 grid grid-cols-2 gap-2 text-xs"><p className="admin-muted">状态 <span className="">{adminLabel(item.status)}</span></p><p className="admin-muted">审核 <span className="">{item.moderation ? adminLabel(item.moderation.action) : '未审核'}</span></p></div><AdminButton type="button" disabled={readOnly || loading || saving} onClick={() => setModerating(item)} className="mt-3 min-h-11 w-full border text-sm disabled:opacity-40">记录审核动作</AdminButton></article>)}</div><Pager busy={loading || saving || Boolean(error)} page={loadedPages.content ?? 1} total={contentTotal} onChange={setContentPage} /></> : <Empty error={error}>暂无可读取的{contentType === 'work' ? '图纸作品' : contentType === 'post' ? '社区帖子' : '评论'}。</Empty>}</div></>}{tab === 'reports' && <><div className="mt-4 grid gap-3 sm:grid-cols-2"><select aria-label="举报处理状态筛选" value={reportStatus} onChange={(event) => { setReportStatus(event.target.value as ReportStatus | 'all'); setReportsPage(1); }} className="min-h-11 border admin-final-surface px-3 text-sm"><option value="all">全部处理状态</option>{REPORT_STATUSES.map((item) => <option key={item} value={item}>{adminLabel(item)}</option>)}</select><select aria-label="举报内容类型筛选" value={reportType} onChange={(event) => { setReportType(event.target.value as ContentType | 'all'); setReportsPage(1); }} className="min-h-11 border admin-final-surface px-3 text-sm"><option value="all">全部内容类型</option><option value="work">{adminLabel('work')}</option><option value="post">{adminLabel('post')}</option><option value="comment">{adminLabel('comment')}</option></select></div><div className="mt-5">{loading ? <Loading /> : reports.length ? <><div className="hidden overflow-x-auto border md:block"><table className="w-full min-w-[920px] text-left text-sm"><thead className="admin-final-surface text-xs admin-muted"><tr><th className="px-4 py-3">举报内容</th><th className="px-4 py-3">原因</th><th className="px-4 py-3">状态</th><th className="px-4 py-3">创建时间</th><th className="px-4 py-3 text-right">操作</th></tr></thead><tbody>{reports.map((report) => <tr key={report.id} className="border-t"><td className="px-4 py-3"><p className="font-mono text-xs">{adminLabel(report.entityType)}:{report.entityId}</p><p className="mt-1 text-xs admin-muted">举报人 {report.reporterUid ?? '-'}</p></td><td className="max-w-sm px-4 py-3"><p className="">{report.reasonCode}</p><p className="mt-1 truncate text-xs admin-muted">{report.description || '-'}</p></td><td className="px-4 py-3">{adminLabel(report.status)}</td><td className="px-4 py-3 admin-muted">{time(report.createdAt)}</td><td className="px-4 py-3 text-right"><AdminButton type="button" onClick={() => setReportDetail(report)} className="min-h-11 px-3">详情 / 处置</AdminButton></td></tr>)}</tbody></table></div><div className="space-y-2 md:hidden">{reports.map((report) => <article key={report.id} className="border admin-final-surface p-3"><div className="flex justify-between gap-3"><p className="min-w-0 truncate font-mono text-xs">{adminLabel(report.entityType)}:{report.entityId}</p><span className="shrink-0 text-xs admin-muted">{adminLabel(report.status)}</span></div><p className="mt-2 text-sm">{report.reasonCode}</p><p className="mt-1 line-clamp-2 text-xs admin-muted">{report.description || '-'}</p><AdminButton type="button" onClick={() => setReportDetail(report)} className="mt-3 min-h-11 w-full border text-sm">详情 / 处置</AdminButton></article>)}</div><Pager busy={loading || saving || Boolean(error)} page={loadedPages.reports ?? 1} total={reportsTotal} onChange={setReportsPage} /></> : <Empty error={error}>暂无符合条件的举报。</Empty>}</div></>}{tab === 'actions' && <><div className="mt-4 grid gap-3 sm:grid-cols-[11rem_minmax(0,1fr)]"><select aria-label="审核内容类型筛选" value={actionEntityType} onChange={(event) => { setActionEntityType(event.target.value as ContentType | 'all'); setActionsPage(1); }} className="min-h-11 border admin-final-surface px-3 text-sm"><option value="all">全部内容类型</option><option value="work">{adminLabel('work')}</option><option value="post">{adminLabel('post')}</option><option value="comment">{adminLabel('comment')}</option></select><input aria-label="审核内容 ID 筛选" value={actionEntityId} maxLength={128} onChange={(event) => { setActionEntityId(event.target.value); setActionsPage(1); }} placeholder="按内容 ID 精确筛选" className="min-h-11 border admin-final-surface px-3 text-sm placeholder:text-slate-600" /></div><div className="mt-5">{loading ? <Loading /> : actions.length ? <><div className="hidden overflow-x-auto border md:block"><table className="w-full min-w-[860px] text-left text-sm"><thead className="admin-final-surface text-xs admin-muted"><tr><th className="px-4 py-3">内容</th><th className="px-4 py-3">动作</th><th className="px-4 py-3">原因</th><th className="px-4 py-3">操作人</th><th className="px-4 py-3">时间</th></tr></thead><tbody>{actions.map((item) => <tr key={item.id} className="border-t"><td className="px-4 py-3 font-mono text-xs">{adminLabel(item.entityType)}:{item.entityId}</td><td className="px-4 py-3">{adminLabel(item.action)}</td><td className="max-w-sm px-4 py-3"><p className="truncate admin-muted">{item.reason || '-'}</p></td><td className="px-4 py-3 font-mono text-xs admin-muted">{item.operatorUid ?? '-'}</td><td className="px-4 py-3 admin-muted">{time(item.createdAt)}</td></tr>)}</tbody></table></div><div className="space-y-2 md:hidden">{actions.map((item) => <article key={item.id} className="border admin-final-surface p-3"><p className="font-mono text-xs">{adminLabel(item.entityType)}:{item.entityId}</p><p className="mt-2 text-sm">{adminLabel(item.action)}</p><p className="mt-1 line-clamp-2 text-xs admin-muted">{item.reason || '-'}</p><p className="mt-2 text-xs admin-muted">{time(item.createdAt)}</p></article>)}</div><Pager busy={loading || saving || Boolean(error)} page={loadedPages.actions ?? 1} total={actionsTotal} onChange={setActionsPage} /></> : <Empty error={error}>暂无符合条件的审核记录。</Empty>}</div></>}{moderating && <ModerationEditor content={moderating} onClose={() => setModerating(null)} onSave={(body) => void createAction(body)} saving={saving} readOnly={readOnly || loading || saving} />}{reportDetail && <ReportDetail report={reportDetail} onClose={() => setReportDetail(null)} update={(status) => void updateReport(reportDetail, status)} saving={saving} readOnly={readOnly || loading || saving} />}{write.confirmation}</section>;
}

export function AdminContentResources({ mode, request }: AdminContentResourcesProps) {
  return <div className="admin-final-modules">{mode === 'colors-assets' ? <ColorsAssetsPanel request={request} /> : <CommunityPanel request={request} />}</div>;
}
